 \begin{align}
w_i &= \frac{1 - \frac{q_i}{\sum_{q \in Q} q}}{n - 1} 
    = \frac{(\sum_{q \in Q} q) - q_i}{(n - 1) \cdot \sum_{q\in Q} q}
\end{align} 
